#[test]
fn test_swap_exchanges_what_the_fields_hold() {
    let d: &mut crate::emon::docprobe::Doc = &mut crate::emon::docprobe::Doc::new();
    crate::port::cells_push(&mut d.a, 1);
    crate::port::cells_push(&mut d.a, 2);
    crate::port::cells_push(&mut d.a, 3);
    crate::port::cells_push(&mut d.b, 9);
    crate::port::cells_swap(&mut d.a, &mut d.b);
    crate::testport::assert_eq(crate::port::cells_len(&mut d.a), 1, "a holds what b held");
    crate::testport::assert_eq(crate::port::cells_at(&mut d.a, 0), 9, "9");
    crate::testport::assert_eq(crate::port::cells_len(&mut d.b), 3, "b holds what a held");
    crate::testport::assert_eq(crate::port::cells_at(&mut d.b, 2), 3, "3");
    crate::port::cells_push(&mut d.a, 10);
    crate::testport::assert_eq(crate::port::cells_len(&mut d.a), 2, "a still grows");
    crate::testport::assert_eq(crate::port::cells_len(&mut d.b), 3, "and b is untouched by it");
}
#[test]
fn test_copy_into_replaces_and_does_not_alias() {
    let d: &mut crate::emon::docprobe::Doc = &mut crate::emon::docprobe::Doc::new();
    crate::port::cells_push(&mut d.a, 5);
    crate::port::cells_push(&mut d.a, 6);
    crate::port::cells_push(&mut d.b, 99);
    crate::port::cells_push(&mut d.b, 98);
    crate::port::cells_push(&mut d.b, 97);
    crate::port::cells_copy_into(&mut d.b, &mut d.a);
    crate::testport::assert_eq(crate::port::cells_len(&mut d.b), 2, "b is a, whatever it held");
    crate::testport::assert_eq(crate::port::cells_at(&mut d.b, 0), 5, "5");
    crate::testport::assert_eq(crate::port::cells_at(&mut d.b, 1), 6, "6");
    crate::port::cells_push(&mut d.a, 7);
    crate::port::cells_set(&mut d.b, 0, 50);
    crate::testport::assert_eq(crate::port::cells_len(&mut d.b), 2, "a growing does not grow the copy");
    crate::testport::assert_eq(crate::port::cells_at(&mut d.a, 0), 5, "and the copy writing does not reach a");
    crate::port::buf_push(&mut d.png, 1);
    crate::port::buf_push(&mut d.png, 255);
    crate::port::buf_push(&mut d.spare, 9);
    crate::port::buf_copy_into(&mut d.spare, &mut d.png);
    crate::testport::assert_eq(crate::port::buf_len(&mut d.spare), 2, "spare is png, whatever it held");
    crate::testport::assert_eq(crate::port::buf_at(&mut d.spare, 1), 255, "255 reads back unsigned");
    crate::port::buf_set(&mut d.spare, 0, 77);
    crate::testport::assert_eq(crate::port::buf_at(&mut d.png, 0), 1, "writing the copy does not reach png");
}
#[test]
fn test_a_clone_is_independent() {
    let d: &mut crate::emon::docprobe::Doc = &mut crate::emon::docprobe::Doc::new();
    crate::port::cells_push(&mut d.a, 4);
    crate::port::buf_push(&mut d.png, 8);
    crate::port::text_ascii(&mut d.out, "ab");
    d.n = 3;
    let e: &mut crate::emon::docprobe::Doc = &mut d.clone();
    crate::testport::assert_eq(crate::port::cells_at(&mut e.a, 0), 4, "the clone has a's cell");
    crate::testport::assert_eq(crate::port::buf_at(&mut e.png, 0), 8, "and png's byte");
    crate::testport::assert_text(&mut e.out, "ab", "and out's text");
    crate::testport::assert_eq(e.n, 3, "and n");
    crate::port::cells_push(&mut e.a, 5);
    crate::port::buf_push(&mut e.png, 6);
    crate::port::text_ascii(&mut e.out, "c");
    e.n = 4;
    crate::port::cells_push(&mut d.a, 7);
    crate::testport::assert_eq(crate::port::cells_len(&mut d.a), 2, "the original grew by its own push only");
    crate::testport::assert_eq(crate::port::cells_at(&mut d.a, 1), 7, "7");
    crate::testport::assert_eq(crate::port::buf_len(&mut d.png), 1, "png untouched by the clone's write");
    crate::testport::assert_text(&mut d.out, "ab", "out untouched");
    crate::testport::assert_eq(d.n, 3, "n untouched");
    crate::testport::assert_eq(crate::port::cells_len(&mut e.a), 2, "the clone grew by its own");
    crate::testport::assert_eq(crate::port::cells_at(&mut e.a, 1), 5, "5, not 7");
    crate::testport::assert_text(&mut e.out, "abc", "the clone's text");
    crate::testport::assert_eq(e.n, 4, "the clone's n");
}
